      { qty: 100, unitPrice: 37 }, // 9% VAT product: 3700
      { qty: 1, unitPrice: 60000 }, // 0% VAT product: 60000
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 72200);
  assert.equal(totals.total, 72200);
});

test('invoiceTotals with a complete invoice from createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // Standard tier, 0% discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }, { sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);
  // 10 * 8500 + 5 * 9500 = 85000 + 47500 = 132500
  // No discount: 0
  // VAT: 85000 * 21% + 47500 * 21% = 17850 + 9975 = 27825
  // total: 132500 - 0 + 27825 = 160325
  assert.equal(totals.subtotal, 132500);
